"use strict";(globalThis.webpackChunkdoqumentation=globalThis.webpackChunkdoqumentation||[]).push([[1933],{60227(a,n,e){e.r(n),e.d(n,{assets:()=>k,contentTitle:()=>r,default:()=>d,frontMatter:()=>s,metadata:()=>i,toc:()=>m});const i=JSON.parse('{"id":"learning/courses/integrating-quantum-and-high-performance-computing/next-steps","title":"Langkah selanjutnya","description":"Pelajaran ini mengkaji keadaan komputasi kuantum dan bagaimana manusia mendekati quantum advantage.","source":"@site/i18n/id/docusaurus-plugin-content-docs/current/learning/courses/integrating-quantum-and-high-performance-computing/next-steps.mdx","sourceDirName":"learning/courses/integrating-quantum-and-high-performance-computing","slug":"/learning/courses/integrating-quantum-and-high-performance-computing/next-steps","permalink":"/learning/courses/integrating-quantum-and-high-performance-computing/next-steps","draft":false,"unlisted":false,"editUrl":"https://github.com/JanLahmann/doQumentation/tree/main/docs/learning/courses/integrating-quantum-and-high-performance-computing/next-steps.mdx","tags":[],"version":"current","frontMatter":{"title":"Langkah selanjutnya","sidebar_label":"Langkah selanjutnya","description":"Pelajaran ini mengkaji keadaan komputasi kuantum dan bagaimana manusia mendekati quantum advantage.","notebook_path":"learning/courses/integrating-quantum-and-high-performance-computing/next-steps.ipynb"},"sidebar":"tutorialsSidebar","previous":{"title":"SQD dan SKQD","permalink":"/learning/courses/integrating-quantum-and-high-performance-computing/sqd-skqd"},"next":{"title":"Ujian | Mengintegrasikan komputasi kuantum dan komputasi performa tinggi","permalink":"/learning/courses/integrating-quantum-and-high-performance-computing/exam"}}');var t=e(74848),u=e(28453);const s={title:"Langkah selanjutnya",sidebar_label:"Langkah selanjutnya",description:"Pelajaran ini mengkaji keadaan komputasi kuantum dan bagaimana manusia mendekati quantum advantage.",notebook_path:"learning/courses/integrating-quantum-and-high-performance-computing/next-steps.ipynb"},r="Prospek dan arah masa depan {#future-outlook-and-direction}",k={},m=[{value:"Mengapa sekarang?",id:"why-now",level:3},{value:"5.1 Gambaran besar",id:"51-the-big-picture",level:2},{value:"Ide-ide besar",id:"big-ideas",level:2},{value:"Prospek IBM untuk masa depan",id:"ibms-outlook-for-the-future",level:2},{value:"Ringkasan",id:"summary",level:2}];function l(a){const n={a:"a",h1:"h1",h2:"h2",h3:"h3",header:"header",img:"img",li:"li",p:"p",ul:"ul",...(0,u.R)(),...a.components};return(0,t.jsxs)(t.Fragment,{children:["\n","\n",(0,t.jsx)(n.header,{children:(0,t.jsx)(n.h1,{id:"future-outlook-and-direction",children:"Prospek dan arah masa depan"})}),"\n",(0,t.jsx)(n.p,{children:"Sejauh ini, kita telah mempelajari motivasi menggunakan komputasi berkinerja tinggi (HPC) dan komputasi kuantum untuk menyelesaikan masalah ilmiah. Kita telah mendefinisikan sumber daya komputasi klasik dan kuantum, termasuk CPU, GPU, dan QPU, serta membahas cara menskalakan dan mengelolanya menggunakan teknik seperti penskalaan vertikal dan horizontal, penjadwalan, dan manajemen beban kerja. Selanjutnya, kita telah menjelajahi model pemrograman untuk QPU (seperti Circuit kuantum dan primitif seperti Sampler dan Estimator) dan komputer klasik, termasuk praktik pemrograman paralel dengan MPI, yang merupakan alat kuat dalam komputasi heterogen kuantum-klasik. Akhirnya, kita telah mempelajari dan mempraktikkan algoritma berbasis sampling kuantum tingkat lanjut, seperti Sample-based Quantum Diagonalization (SQD) dan Sample-based Krylov Quantum Diagonalization (SKQD). Algoritma-algoritma ini memanfaatkan metode subruang untuk memperkirakan secara akurat energi keadaan dasar molekul dan material dengan menyiapkan dan mengambil sampel keadaan kuantum, yang mendefinisikan subruang untuk diagonalisasi klasik, sebuah kombinasi model pemrograman berbeda pada sekumpulan sumber daya heterogen. Dengan konsep-konsep dasar superkomputing kuantum dan klasik ini, kita tidak lagi berbicara tentang satu menggantikan yang lain, tetapi tentang menciptakan sistem terpadu yang kuat yang bekerja secara sinergis \u2014 sebuah kombinasi yang siap membawa fajar quantum advantage."}),"\n",(0,t.jsx)(n.h3,{id:"why-now",children:"Mengapa sekarang?"}),"\n",(0,t.jsxs)(n.p,{children:['Komunitas sudah melewati tonggak "quantum utility" \u2014 di mana komputer kuantum pertama kali terbukti menjadi alat ilmiah yang berguna yang mampu melakukan komputasi di luar simulasi brute-force klasik. Era utilitas ini dimulai dengan ',(0,t.jsx)(n.a,{href:"https://www.nature.com/articles/s41586-023-06096-3",children:"makalah utilitas"}),' yang terkenal yang ditampilkan di sampul Nature pada tahun 2023, dan berlanjut hingga mencakup lusinan publikasi oleh mitra, klien, dan peneliti di IBM Quantum\xae. Kini, fokus telah bergeser ke batas kritis berikutnya: mencapai quantum advantage. Untuk waktu yang lama, istilah "quantum advantage" mengalami definisi yang tidak tepat. ',(0,t.jsx)(n.a,{href:"https://arxiv.org/abs/2506.20658",children:"Makalah ini"})," telah mengemukakan definisi konkret, yang akan kita gunakan di sini. Secara khusus, quantum advantage menunjukkan pelaksanaan tugas pemrosesan informasi pada perangkat keras kuantum yang memenuhi dua kriteria penting:"]}),"\n",(0,t.jsx)(n.p,{children:"i) Kebenaran output dapat divalidasi secara ketat, dan"}),"\n",(0,t.jsx)(n.p,{children:"ii) Dilakukan dengan pemisahan kuantum yang secara jelas menawarkan efisiensi, efektivitas biaya, atau akurasi yang lebih unggul dari yang dapat dicapai dengan komputasi klasik saja."}),"\n",(0,t.jsx)(n.p,{children:"Diharapkan bahwa quantum advantage akan mulai muncul pada akhir 2026 dan akan terwujud melalui pemanfaatan sumber daya kuantum dan HPC bersama-sama. Pelajaran ini menguraikan visi inti untuk paradigma baru ini, merinci ide-ide kunci ke depan, dan menyajikan prospek masa depan yang didasarkan pada kerangka terverifikasi dan agnostik platform untuk mendemonstrasikan dan mewujudkan quantum advantage yang sejati."}),"\n",(0,t.jsx)(n.h2,{id:"51-the-big-picture",children:"5.1 Gambaran besar"}),"\n",(0,t.jsx)(n.p,{children:'Untuk pertama kalinya, kita menyaksikan titik balik signifikan dalam sejarah komputasi \u2014 era quantum-centric supercomputing (QCSC), sebuah paradigma yang sedang berkembang yang mengintegrasikan secara ketat unit pemrosesan kuantum (QPU) dengan superkomputer klasik. Visinya bukan agar sistem kuantum menggantikan sistem klasik, tetapi untuk mendemonstrasikan bahwa arsitektur heterogen ini \u2014 di mana "kuantum plus klasik" dapat mengungguli klasik saja \u2014 adalah jalur terkuat ke depan. Dalam model ini, QPU dibayangkan sebagai ko-prosesor khusus, bekerja berdampingan dengan CPU dan GPU untuk menangani masalah komputasi yang tidak dapat ditangani oleh komputer klasik.'}),"\n",(0,t.jsx)(n.p,{children:"Potensi penuh arsitektur baru ini hanya dapat diwujudkan dengan menempatkan alat-alat kuat ini di tangan sebanyak mungkin pengguna. Visi ini sudah terbentuk melalui penyebaran sistem kuantum di pusat komputasi berkinerja tinggi (HPC) yang mapan dan pengembangan perangkat lunak, seperti plugin Slurm kuantum, yang memperlancar integrasinya ke dalam alur kerja klasik yang ada. Dengan membuat sistem heterogen ini lebih mudah diakses oleh komunitas penelitian yang lebih luas, kita mendorong lingkungan yang diperlukan untuk inovasi dan penemuan."}),"\n",(0,t.jsx)(n.p,{children:"Strategi menggabungkan teknologi terintegrasi dengan basis pengguna yang luas inilah yang menurut kami akan membawa komunitas mencapai quantum advantage dalam waktu dekat. Quantum advantage bukan merupakan tonggak tunggal yang definitif melainkan sebuah proses \u2014 serangkaian demonstrasi yang semakin kuat yang akan diteliti, direproduksi, dan ditantang oleh komunitas hingga konsensus ilmiah tercapai. Ini adalah jalur untuk mendemonstrasikan, pada akhir 2026, contoh pertama yang kredibel dan terverifikasi di mana cara komputasi baru ini menyelesaikan masalah praktis lebih efisien, hemat biaya, atau akurat dari yang dapat dicapai dengan komputasi klasik saja."}),"\n",(0,t.jsx)(n.p,{children:(0,t.jsx)(n.img,{alt:"A diagram showing the cost of simulations as a function of increasing circuit complexity for both classical computers and quantum computers with error mitigation. Once the curves cross, the space between them corresponds to quantum advantage.",src:e(67435).A+"",width:"793",height:"540"})}),"\n",(0,t.jsx)(n.h2,{id:"big-ideas",children:"Ide-ide besar"}),"\n",(0,t.jsx)(n.p,{children:"Untuk mewujudkan visi ini, beberapa pertanyaan dan ide kritis harus ditangani."}),"\n",(0,t.jsxs)(n.ul,{children:["\n",(0,t.jsxs)(n.li,{children:["\n",(0,t.jsx)(n.p,{children:"Partisi beban kerja yang optimal: Di sisi perangkat lunak, tantangannya terletak pada pengelolaan alur kerja hibrida yang kompleks. Mengatur pelaksanaan tugas yang mulus di seluruh sumber daya kuantum dan klasik memerlukan alat yang canggih. Ini mencakup Middleware Kuantum-HPC dan Infrastruktur Runtime yang dirancang untuk menangani penjadwalan pekerjaan, manajemen sumber daya, dan aliran data dalam lingkungan heterogen ini. Selanjutnya, mengembangkan teknik untuk memparalelkan Circuit kuantum secara efektif atau memecahnya menjadi bagian-bagian yang lebih kecil dan dapat dikelola sangat penting untuk memaksimalkan utilitas perangkat keras kuantum saat ini."}),"\n"]}),"\n",(0,t.jsxs)(n.li,{children:["\n",(0,t.jsx)(n.p,{children:'Toleransi kesalahan tingkat sistem: Solusi utama untuk melindungi informasi kuantum dari noise adalah komputasi kuantum toleran kesalahan (FTQC), di mana informasi dikodekan ke dalam "qubit logis" yang kuat. Sementara kode koreksi kesalahan quantum low-density parity-check (qLDPC) yang muncul menawarkan jalur untuk mengurangi overhead sumber daya yang sangat besar yang diperlukan, implementasi toleransi kesalahan penuh tidak diperkirakan dapat dilakukan dalam waktu dekat. Pada saat yang sama, mitigasi kesalahan menggunakan pasca-pemrosesan klasik untuk mengurangi atau menghilangkan bias dalam perhitungan yang disebabkan oleh noise, yang juga merupakan elemen penting dalam mencapai sistem kuantum toleran kesalahan tingkat sistem. Metode mitigasi kesalahan yang kuat sudah diterapkan sebagai layanan, menunjukkan kekuatan arsitektur QCSC. Misalnya:'}),"\n",(0,t.jsxs)(n.ul,{children:["\n",(0,t.jsxs)(n.li,{children:[(0,t.jsx)(n.a,{href:"/guides/algorithmiq-tem",children:"Tensor Network Error Mitigation"})," (TEM) dari Algorithmiq mengelola noise dalam pasca-pemrosesan perangkat lunak, memanfaatkan sumber daya HPC klasik untuk memperluas jangkauan QPU saat ini."]}),"\n",(0,t.jsxs)(n.li,{children:[(0,t.jsx)(n.a,{href:"/guides/qedma-qesem",children:"Quantum Error Suppression and Error Mitigation"})," (QESEM) dari Qedma menggabungkan penekanan kesalahan tingkat perangkat keras dengan mitigasi untuk meningkatkan keandalan komputasi kuantum dalam skala besar."]}),"\n"]}),"\n"]}),"\n",(0,t.jsxs)(n.li,{children:["\n",(0,t.jsx)(n.p,{children:"Demokratisasi akses: Membuat sistem hibrida yang kuat ini dapat diakses secara luas adalah kunci untuk mempercepat inovasi. Ini sudah terwujud melalui penyebaran fisik sistem kuantum di pusat HPC dan rilis plugin Slurm untuk integrasi yang lebih lancar. Untuk memperlancar integrasi ini, kedua perusahaan telah merilis plugin Slurm, sehingga beban kerja kuantum dapat dikelola dengan penjadwal HPC standar. Selanjutnya, tumpukan perangkat lunak komprehensif seperti Qiskit menyediakan lingkungan runtime berbasis cloud untuk eksekusi Circuit kuantum dengan latensi rendah, mengatur tugas hibrida yang kompleks dan menyediakan alat untuk kompilasi, optimasi, dan mitigasi kesalahan. Perangkat keras kuantum akses terbuka dan paket pengembangan sumber terbuka pasti akan memainkan peran penting."}),"\n"]}),"\n"]}),"\n",(0,t.jsx)(n.h2,{id:"ibms-outlook-for-the-future",children:"Prospek IBM untuk masa depan"}),"\n",(0,t.jsxs)(n.p,{children:[(0,t.jsx)(n.a,{href:"https://www.ibm.com/quantum/hardware#roadmap",children:"Peta Jalan Pengembangan IBM Quantum"})," adalah demonstrasi yang baik tentang gambaran besar dan ide-ide besar ini."]}),"\n",(0,t.jsx)(n.p,{children:(0,t.jsx)(n.img,{alt:"The IBM Quantum Development Roadmap",src:e(97895).A+"",width:"960",height:"536"})}),"\n",(0,t.jsx)(n.p,{children:'Peta jalan perangkat keras IBM Quantum didorong oleh fokus pada peningkatan skala dan konektivitas qubit. Seri Nighthawk (2025-2028) menggunakan arsitektur kisi persegi baru untuk meningkatkan konektivitas, sementara prosesor Loon (2025) memperkenalkan "c-couplers" untuk memungkinkan konektivitas qubit non-lokal, yang sangat penting untuk komputasi kuantum toleran kesalahan (FTQC). Peta jalan ini berpuncak pada sistem IBM Quantum Starling (2029) dan Blue Jay (2033+), yang dirancang untuk menghadirkan komputasi toleran kesalahan skala besar dengan jutaan Gate dan ribuan qubit logis.'}),"\n",(0,t.jsx)(n.p,{children:"Strategi perangkat lunak dan middleware dibangun di atas empat tujuan utama: mengeksekusi secara akurat, mengatur beban kerja, menemukan algoritma baru, dan menerapkannya pada kasus penggunaan tertentu. Peta jalan mencakup peningkatan berkelanjutan seperti circuit dinamis skala utilitas (2025) dan alat profiling baru (2026) untuk memastikan eksekusi yang efisien. Untuk orkestrasi beban kerja, C-API (2025) dan akselerator alur kerja masa depan (2027) akan mengintegrasikan komputasi kuantum dan HPC klasik. Selanjutnya, IBM\xae akan memperkenalkan alat pemetaan utilitas (2026) dan perpustakaan Circuit baru (2029) untuk memfasilitasi penemuan dan penerapan algoritma baru."}),"\n",(0,t.jsx)(n.h2,{id:"summary",children:"Ringkasan"}),"\n",(0,t.jsx)(n.p,{children:"Kita telah menjelajahi gambaran besar dan ide-ide besar di balik tujuan QCSC, dan kita melihat peta jalan IBM tentang pengembangan dan inovasi komputasi kuantum. Perjalanan ini, seperti yang telah kita lihat, adalah maraton, bukan sprint. Sementara IBM berkomitmen untuk menghadirkan komputer kuantum yang semakin kuat, kemajuan kita hanya satu bagian dari persamaan. Sangat penting bahwa komunitas kuantum terus mengembangkan algoritma baru, membuka jalan bagi aplikasi yang benar-benar akan membawa komputasi kuantum yang berguna ke dunia."}),"\n",(0,t.jsx)(n.p,{children:"Untuk mencapai ini, kita harus bekerja sama. Ini berarti menetapkan masalah benchmarking yang terstandar dengan bantuan para ahli klasik untuk memastikan relevansi dan keadilan. Ini juga memerlukan publikasi metodologi dan kumpulan data yang terperinci untuk memungkinkan reproduktifitas, dan pemeliharaan papan peringkat akses terbuka untuk melacak kemajuan kolektif kita."}),"\n",(0,t.jsx)(n.p,{children:"Belum pernah ada waktu yang lebih menarik untuk menjadi bagian dari komunitas ini. Dengan mengadopsi praktik terbaik ini dan melanjutkan eksplorasi kita, kita dapat bekerja sama untuk mewujudkan potensi penuh dari quantum advantage."})]})}function d(a={}){const{wrapper:n}={...(0,u.R)(),...a.components};return n?(0,t.jsx)(n,{...a,children:(0,t.jsx)(l,{...a})}):l(a)}},67435(a,n,e){e.d(n,{A:()=>i});const i=e.p+"assets/images/advantage-f7fc7a67f0f1aac33e4c95b7965b10c0.svg"},97895(a,n,e){e.d(n,{A:()=>i});const i=e.p+"assets/images/roadmap-c4a476cff4c185739f3c99c69c717523.svg"},28453(a,n,e){e.d(n,{R:()=>s,x:()=>r});var i=e(96540);const t={},u=i.createContext(t);function s(a){const n=i.useContext(u);return i.useMemo(function(){return"function"==typeof a?a(n):{...n,...a}},[n,a])}function r(a){let n;return n=a.disableParentContext?"function"==typeof a.components?a.components(t):a.components||t:s(a.components),i.createElement(u.Provider,{value:n},a.children)}}}]);